package project.init.account.controller;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.RequestBody;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RestController;import project.init.account.domain.req.CreateAccountReq;import project.init.account.domain.req.FilterAccountReq;import project.init.account.domain.resp.AccountResp;import project.init.account.domain.resp.AccountRespFilter;import project.init.account.service.AccountService;import project.init.framework.authen.BearerContextHolder;import java.util.List;@Slf4j@RestController@RequestMapping("/accounts")@RequiredArgsConstructorpublic class AccountController {    private final AccountService accountService;    @PostMapping("/filter")    public ResponseEntity<List<AccountRespFilter>> filter(@RequestBody FilterAccountReq req) {        log.info("[filter] [{}] {}", BearerContextHolder.get().getAccountCode(), req);        List<AccountRespFilter> accounts = accountService.filter(req);        return new ResponseEntity<>(accounts, HttpStatus.OK);    }    @PostMapping("/create")    public ResponseEntity<AccountResp> create(@RequestBody CreateAccountReq req) {        log.info("[create] [{}] add({})", BearerContextHolder.get().getAccountCode(), req);        AccountResp accountSaved = accountService.create(req);        return new ResponseEntity<>(accountSaved, HttpStatus.OK);    }}